        if (geqN(a,b)){{ u64 t[LIMBS]; subN(a,b,t); for(int j=0;j<LIMBS;j++) a[j]=b[j]; for(int j=0;j<LIMBS;j++) b[j]=t[j]; }}
        else {{ u64 t[LIMBS]; subN(b,a,t); for(int j=0;j<LIMBS;j++) b[j]=t[j]; }}
