    u64 t[LIMBS+2]; for (int i=0;i<LIMBS+2;i++) t[i]=0;
    for (int i=0;i<LIMBS;i++){{
        u128 C=0;
        for (int j=0;j<LIMBS;j++){{ u128 x=(u128)a[j]*(u128)b[i]+(u128)t[j]+C; t[j]=(u64)x; C=x>>64; }}
