let c_parity: u32 = if (&c % 2i32) == BigInt::from(0) { 0 } else { 1 };
let p_still_open = k < p_bits;
let q_still_open = k < q_bits;

if k < short {
    // both sides still open — branch p_bit, derive q_bit from parity
    for &p_bit in &[0u32, 1u32] {
        let q_bit = (c_parity + p_bit) % 2;
        let new_p = if p_bit == 1 { &p_val + &pow2(k) } else { p_val.clone() };
        let new_q = if q_bit == 1 { &q_val + &pow2(k) } else { q_val.clone() };
        let cross = BigInt::from(p_bit * q_bit) * BigInt::from(pow2(k));
        let numerator = &c + BigInt::from(p_bit) * BigInt::from(q_val.clone())
            + BigInt::from(q_bit) * BigInt::from(p_val.clone())
            + cross;
        let new_c = numerator / BigInt::from(2);
        if let Some(r) = hensel_unbraid(n, p_bits, q_bits, k + 1, new_p, new_q, new_c, budget) {
            return Some(r);
        }
        if budget.nodes > budget.cap { return None; }
    }
    None
} else {
    // one side is fully fixed now — the other's next bit is FORCED, no branch
    let (bit, new_p, new_q) = if p_still_open {
        let bit = c_parity; // q's contribution is fixed (q_bit=0 beyond q_bits), so p_bit ≡ c_parity
        (bit, if bit == 1 { &p_val + &pow2(k) } else { p_val.clone() }, q_val.clone())
    } else if q_still_open {
        let bit = c_parity;
        (bit, p_val.clone(), if bit == 1 { &q_val + &pow2(k) } else { q_val.clone() })
    } else {
        return if c == BigInt::from(0) { Some((p_val, q_val)) } else { None };
    };
    let numerator = if p_still_open {
        &c + BigInt::from(bit) * BigInt::from(q_val.clone())
    } else {
        &c + BigInt::from(bit) * BigInt::from(p_val.clone())
    };
    let new_c = numerator / BigInt::from(2);

